raft", "id": "6981ec61-f0b4-5b54-8bba-6e5b658d0a8a", "subject_id": "3e68f67b-55fd-5e13-a922-5e8702e6910a", "source_id": "056491db-48bf-5982-83a0-a2a41c8a36fa"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧唐书》卷二十下亦载六月戊子敕七官赐自尽。", "citation": "《旧唐书》卷二十下，段落 jiu-tangshu-b729c4ac3d3b-p003337；EPUB电子本，纸本及异文待核", "note": "原文：委御史台差人所在州縣各賜自盡；核对说明：旧书敕文此前列七名，摘录只证赐死命令；同段另叙白马驿。", "status": "draft", "id": "6d2849a8-029b-55c7-b51b-21f093af1134", "subject_id": "184006b5-be2d-50e0-b713-e75c268f4f8c", "source_id": "5a90ad1c-67a0-57dd-a95e-c075c127658d"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧唐书》卷二十下记七人于滑州白马驿遇害并投尸于河。", "citation": "《旧唐书》卷二十下，段落 jiu-tangshu-b729c4ac3d3b-p003337；EPUB电子本，纸本及异文待核", "note": "原文：時樞等七人已至滑州，皆並命于白馬驛，全忠令投屍於河；核对说明：旧书所记七人范围较主书“三十余人”窄；不把两种计数强合。", "status": "draft", "id": "d8700078-5656-5c80-ba69-545c432769c8", "subject_id": "a29066ff-9dd3-539b-9c58-e9e1ed3f9c84", "source_id": "5a90ad1c-67a0-57dd-a95e-c075c127658d"}, {"subject_table": "event", "field_path": "description", "claim_text": "《新五代史》卷三十五记七名朝官同日赐死白马驿，并总述数百人受贬死。", "citation": "《新五代史》卷三十五，段落 xin-wudaishi-b08f244b9241-p001239；EPUB电子本，纸本及异文待核", "note": "原文：皆以無罪貶，同日賜死于白馬驛；核对说明：“數百人”是该书对更广范围的总述，不当成本次一夕被杀人数；新书所系年与主书有异。", "status": "draft", "id": "11a03590-bfe7-5207-acf3-ffce51f9622e", "subject_id": "a29066ff-9dd3-539b-9c58-e9e1ed3f9c84", "source_id": "cb93a58f-5176-53b3-af73-e04f9c5842ed"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》卷十八亦记李振清流、浊流之言。", "citation": "《旧五代史》卷十八，段落 jiu-wudaishi-205deb4a7860-p000650；EPUB电子本，纸本及异文待核", "note": "原文：此輩自謂清流，宜投於黃河，永為濁流；核对说明：同书还记屡举不第；两书言辞略异，保留原句。", "status": "draft", "id": "8cf9f5b4-76f0-586b-b273-df2926e2d6cb", "subject_id": "450f343d-8ac5-5b53-a343-3647094f9d16", "source_id": "9a00173d-b133-50d7-8fb4-4c4a8e89636a"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》卷十八记李振自汴入洛使朝士被贬，时称鸱鸮。", "citation": "《旧五代史》卷十八，段落 jiu-wudaishi-205deb4a7860-p000650；EPUB电子本，纸本及异文待核", "note": "原文：振每自汴入洛，朝中必有貶竄，故唐朝人士目為「鴟鴞」；核对说明：主书简体作鸱枭，旧书原文作鴟鴞；是称谓字形异说，不另建人物。", "status": "draft", "id": "ecc019fa-32e1-54e4-9380-eef7c223cb69", "subject_id": "0555dc77-6cd5-5e93-9451-763ff9c74b53", "source_id": "9a00173d-b133-50d7-8fb4-4c4a8e89636a"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧唐书》卷二十下己丑敕裴贽贬青州司户。", "citation": "《旧唐书》卷二十下，段落 jiu-tangshu-b729c4ac3d3b-p003337；EPUB电子本，纸本及异文待核", "note": "原文：可責授青州司戶；核对说明：旧书此摘录只证贬官，不证“寻赐死”具体日。", "status": "draft", "id": "fdc8e228-2b34-5f04-bf1f-3cf89315ce0c", "subject_id": "16265840-df9b-5f41-b42c-367fa24cb292", "source_id": "5a90ad1c-67a0-57dd-a95e-c075c127658d"}, {"subject_table": "event", "field_path": "description", "claim_text": "《新五代史》卷三十五记张文蔚力讲解，朝士多获全活。", "citation": "《新五代史》卷三十五，段落 xin-wudaishi-b08f244b9241-p001243；EPUB电子本，纸本及异文待核", "note": "原文：文蔚力講解之，朝士多賴以全活；核对说明：新书对张文蔚劝解效果记述较主书具体，不据此推断确数。", "status": "draft", "id": "d0bf9e81-d94a-5269-a93c-bb74e13f5357", "subject_id": "4a236805-7131-5dc6-bdf2-3ab537e97a30", "source_id": "49471974-1c4e-5d93-af1b-8e72c1401c30"}]'::jsonb)
